-- Step 4 — Canonical, user-owned Master CV source.
--
-- `cv_versions` remains the targeted opportunity-artifact table. Master CV
-- revisions are deliberately stored separately and are never generated by
-- this migration or its save function.

begin;

create table if not exists public.master_cv_versions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  revision integer not null check (revision > 0),
  is_current boolean not null default false,
  content text,
  source_reference text,
  change_summary text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint master_cv_versions_has_material check (
    nullif(btrim(content), '') is not null
    or nullif(btrim(source_reference), '') is not null
  ),
  constraint master_cv_versions_content_size check (
    content is null or char_length(content) <= 2000000
  ),
  constraint master_cv_versions_source_reference_size check (
    source_reference is null or char_length(source_reference) <= 2048
  ),
  constraint master_cv_versions_change_summary_size check (
    change_summary is null or char_length(change_summary) <= 500
  )
);

create unique index if not exists master_cv_versions_user_revision_uidx
  on public.master_cv_versions (user_id, revision);
create unique index if not exists master_cv_versions_one_current_uidx
  on public.master_cv_versions (user_id)
  where is_current = true;
create index if not exists master_cv_versions_user_created_idx
  on public.master_cv_versions (user_id, created_at desc);

drop trigger if exists master_cv_versions_updated_at_trigger on public.master_cv_versions;
create trigger master_cv_versions_updated_at_trigger
before update on public.master_cv_versions
for each row execute function public.set_updated_at();

comment on table public.master_cv_versions is
  'User-supplied canonical Master CV revisions. Separate from targeted cv_versions artifacts.';
comment on column public.master_cv_versions.content is
  'User-supplied CV content only; this table does not generate or fabricate claims.';
comment on column public.master_cv_versions.source_reference is
  'Optional bounded reference to the user-supplied source, such as a private storage object.';

alter table public.master_cv_versions enable row level security;

-- Browser sessions may read their own revisions, but cannot write rows
-- directly. The validated RPC below is the only authenticated save/import
-- path, so clients cannot choose another owner, revision, or current flag.
revoke all on table public.master_cv_versions from public, anon, authenticated;
grant select on table public.master_cv_versions to authenticated;

drop policy if exists "Users can read their master CV versions" on public.master_cv_versions;
create policy "Users can read their master CV versions"
  on public.master_cv_versions for select to authenticated
  using ((select auth.uid()) = user_id);

-- Keep the privileged implementation outside the exposed public schema. The
-- public RPC below is an invoker wrapper with the only client-facing grant.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

create or replace function private.save_master_cv_impl(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_content text;
  v_source_reference text;
  v_change_summary text;
  v_revision integer;
  v_id uuid;
  v_created_at timestamptz;
  v_updated_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'authenticated user is required';
  end if;
  if coalesce(jsonb_typeof(p_payload), '') <> 'object' then
    raise exception 'p_payload must be a JSON object';
  end if;

  -- Ownership and revision are server-controlled. A caller may only save
  -- material that arrived in this request; no default or generated CV text is
  -- introduced here.
  if p_payload ? 'user_id' then
    raise exception 'user_id is not accepted; ownership comes from auth.uid()';
  end if;
  if p_payload ? 'revision' or p_payload ? 'is_current' then
    raise exception 'revision and is_current are server-controlled';
  end if;
  if p_payload ? 'content'
    and p_payload->'content' <> 'null'::jsonb
    and jsonb_typeof(p_payload->'content') <> 'string' then
    raise exception 'content must be a string or null';
  end if;
  if p_payload ? 'source_reference'
    and p_payload->'source_reference' <> 'null'::jsonb
    and jsonb_typeof(p_payload->'source_reference') <> 'string' then
    raise exception 'source_reference must be a string or null';
  end if;
  if p_payload ? 'change_summary'
    and p_payload->'change_summary' <> 'null'::jsonb
    and jsonb_typeof(p_payload->'change_summary') <> 'string' then
    raise exception 'change_summary must be a string or null';
  end if;

  v_content := nullif(btrim(p_payload->>'content'), '');
  v_source_reference := nullif(btrim(p_payload->>'source_reference'), '');
  v_change_summary := nullif(btrim(p_payload->>'change_summary'), '');

  if v_content is null and v_source_reference is null then
    raise exception 'content or source_reference is required';
  end if;
  if v_source_reference ~ '[[:cntrl:]]' then
    raise exception 'source_reference contains control characters';
  end if;
  if v_content is not null and char_length(v_content) > 2000000 then
    raise exception 'content exceeds the 2000000 character limit';
  end if;
  if v_source_reference is not null and char_length(v_source_reference) > 2048 then
    raise exception 'source_reference exceeds the 2048 character limit';
  end if;
  if v_change_summary is not null and char_length(v_change_summary) > 500 then
    raise exception 'change_summary exceeds the 500 character limit';
  end if;

  -- Serialize revision allocation per user so concurrent imports cannot pick
  -- the same revision number.
  perform pg_advisory_xact_lock(4, hashtext(v_user_id::text));
  select coalesce(max(revision), 0) + 1
    into v_revision
    from public.master_cv_versions
   where user_id = v_user_id;

  update public.master_cv_versions
     set is_current = false
   where user_id = v_user_id and is_current = true;

  insert into public.master_cv_versions (
    user_id, revision, is_current, content, source_reference, change_summary
  )
  values (
    v_user_id, v_revision, true, v_content, v_source_reference, v_change_summary
  )
  returning id, created_at, updated_at
    into v_id, v_created_at, v_updated_at;

  return jsonb_build_object(
    'id', v_id,
    'user_id', v_user_id,
    'revision', v_revision,
    'is_current', true,
    'content', v_content,
    'source_reference', v_source_reference,
    'change_summary', v_change_summary,
    'created_at', v_created_at,
    'updated_at', v_updated_at
  );
end;
$$;

revoke all on function private.save_master_cv_impl(jsonb) from public, anon, authenticated;
grant execute on function private.save_master_cv_impl(jsonb) to authenticated;

create or replace function public.save_master_cv(p_payload jsonb)
returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select private.save_master_cv_impl(p_payload);
$$;

revoke all on function public.save_master_cv(jsonb) from public, anon, authenticated;
grant execute on function public.save_master_cv(jsonb) to authenticated;

comment on function public.save_master_cv(jsonb) is
  'Validated authenticated save/import path for user-supplied Master CV material; never fabricates content.';

commit;
